/** Opt-in finite trade. The same data owns cash, cargo, listings and private boxes while unloaded. */
public final class CityTrade extends SavedData {
 public static final class Config {public double cityMultiplier=1.5,perceptionError=.1;public double[] targets={5,1.5,.25,.5};public int bakeFee=2;public int listingTicks=600,grainStep=12,consumerStep=4,travelTicks=2400,supplierCap=6;}
 static void validate(Config c){CityEconomy.require(c!=null&&Double.isFinite(c.cityMultiplier)&&c.cityMultiplier>=.5&&c.cityMultiplier<=10&&Double.isFinite(c.perceptionError)&&c.perceptionError>=0&&c.perceptionError<=.5&&c.targets!=null&&c.targets.length==4,"基准倍率/估价误差无效");for(double v:c.targets)CityEconomy.require(Double.isFinite(v)&&v>=.01&&v<=1000,"人口库存系数越界");CityEconomy.require(c.bakeFee>=1&&c.bakeFee<=100,"代烤费越界");CityEconomy.require(c.listingTicks>=100&&c.listingTicks<=6000&&c.grainStep>=1&&c.grainStep<=192&&c.consumerStep>=1&&c.consumerStep<=64&&c.travelTicks>=1200&&c.travelTicks<=48000&&c.supplierCap>=1&&c.supplierCap<=1000,"批次/路程/供货上限越界");}
 public static final class Business {
  public long bakeSegment=-1,bakeUnits,bakeOrders,bakeFees,bakeOwnUnits;public long foodDrawn,foodDrawCostCents;public long breadDay=-1;public int breadRemaining,breadPlanned;public TradeRules.Lot[] meatCargo=meats(),meatListed=meats();
  public UUID id,city,worker,owner,employer;public boolean closing;public long lastIncome=-1;public double outputCredit;public String kind="",account="",status="待命";public long site,nextTrip,arrive,departedDay=-1;public int phase,planned;public boolean reverse;public double perception=1;
  public TradeRules.Lot[] stock=TradeRules.lots(),listed=TradeRules.lots(),cargo=TradeRules.lots();
  public boolean[] listing=new boolean[4];public int[] batch=new int[4];public long materialUnits,materialSales,purchases,sales,wages,tax,expenseCents,profitCents,trips,emptyTrips;public int[] bought=new int[4],sold=new int[4];
 }
 public static final class Town {
  public long breadPlanDay=-1;public boolean foodStarted;public long foodClock;public UUID city,partner;public boolean urban,localOnly,model;public int familyCursor;public int level=1;public double standardMultiplier=1;public TradeRules.Price[] prices={new TradeRules.Price(),new TradeRules.Price(),new TradeRules.Price(),new TradeRules.Price()};
 }
 public static final class Run {
  public boolean ready,running,done;public UUID city,village;public long startClock,startGame,lastSample,endClock;public String startedAt="",endedAt="",failure="";public long initialMigrationSilver,initialDeaths;public long initialMoney,initialGrain,initialMeat,initialGoods,initialHarvest,initialBreadEaten,initialMeatProduced,initialMeatEaten;
  public long foodImprovementUnits,foodImprovementSilver,foodBarterWheat;public long supplierInput,urbanHarvest,urbanEaten,meatCooked,barter,consumerSales,grainTrades;public double maxStepMs;public List<Map<String,Object>> samples=new ArrayList<>();public Map<String,Boolean> checks=new LinkedHashMap<>();
 }
 public static final class State {public Map<UUID,CityRelief.Policy> relief=new LinkedHashMap<>();public Map<UUID,CityRelief.Unemployment> unemployment=new LinkedHashMap<>();public CityModelLab.Run modelRun=new CityModelLab.Run();public Map<UUID,CityCurrency.Policy> currencies=new LinkedHashMap<>();public Map<String,UUID> sellerCursor=new LinkedHashMap<>();public long directGrain;public Map<UUID,UUID> grainStallCursor=new LinkedHashMap<>();public Map<UUID,FoodDecay.Loss> decay=new LinkedHashMap<>();public long reverseGrain,routeMeat;public long jointTransactions,jointMeat,jointGrain;public CityRiskLab.Run riskRun=new CityRiskLab.Run();public Map<UUID,FamilyBudget.Budget> familyBudgets=new LinkedHashMap<>();public long registrationRevision;public int schema=1;public Config config=new Config();public long configRevision;public Map<UUID,Town> towns=new LinkedHashMap<>();public Map<UUID,Business> businesses=new LinkedHashMap<>();public Map<String,Integer> taxTails=new LinkedHashMap<>();public Map<UUID,Long> shoppingDay=new LinkedHashMap<>();public Run run=new Run();public Map<UUID,Long> staffIncomeAt=new LinkedHashMap<>();public Map<UUID,FamilyLivelihood.Home> households=new LinkedHashMap<>();public long nextStep,lastSegment=-1;public boolean checking;}
 static TradeRules.Lot[] meats(){var a=new TradeRules.Lot[10];for(int i=0;i<10;i++)a[i]=new TradeRules.Lot();return a;}
 State state=new State();
 public static CityTrade get(MinecraftServer s){return s.overworld().getDataStorage().computeIfAbsent(new Factory<>(CityTrade::new,CityTrade::load),"city_finite_trade");}
 static CityTrade load(CompoundTag t,HolderLookup.Provider r){var d=new CityTrade();if(t.contains("Json"))d.state=CityEconomy.JSON.fromJson(new String(t.getByteArray("Json"),StandardCharsets.UTF_8),State.class);CityEconomy.require(d.state.schema==1&&d.state.towns.size()<=128&&d.state.businesses.size()<=512&&d.state.taxTails.size()<=8192,"有限贸易数据超限");for(var b:d.state.businesses.values()){CityEconomy.require(b.stock.length==4&&b.listed.length==4&&b.cargo.length==4&&b.meatCargo.length==10&&b.meatListed.length==10,"货物种类不匹配");for(var lots:List.of(b.stock,b.listed,b.cargo,b.meatCargo,b.meatListed))for(var lot:lots)CityEconomy.require(lot.count>=0&&lot.cents>=0,"库存/成本无效");}validate(d.state.config);FamilyBudget.validate(d.state.familyBudgets);return d;}
 public CompoundTag save(CompoundTag t,HolderLookup.Provider r){t.putByteArray("Json",CityEconomy.JSON.toJson(state).getBytes(StandardCharsets.UTF_8));return t;}
 void prepare(MinecraftServer s){for(var town:state.towns.values()){town.localOnly=true;var c=CityData.get(s).require(town.city);CityHousing.seedCatalog(c.housing);c.housing.testSupply=true;c.housing.constructionSupplyOnly=true;for(var m:c.housing.market.values()){m.cap=128;m.supply=4;}}for(var b:state.businesses.values()){if(b.owner==null)b.owner=b.worker;if(b.lastIncome<0)b.lastIncome=RuralSettlement.get(s).state.simulationTicks;}setDirty();CityData.get(s).setDirty();}
 void exits(MinecraftServer s,long now){var d=RuralSettlement.get(s);for(var b:state.businesses.values()){if(b.owner==null)b.owner=b.worker;if(b.lastIncome<0)b.lastIncome=now;if(!RuralSettlement.active(s,b.city)||b.closing||!Set.of("baker","supplier","procurement").contains(b.kind)||b.phase!=0)continue;var owner=d.state.people.get(b.owner);if(!RuralSuccession.capable(owner))continue;var f=d.state.families.get(owner.family);int food=RuralRules.count(d.stocks(f.id),true)+RuralRules.count(d.stocks(f.id),false);long cash=familyMoney(s,f)+CityEconomy.get(s).balance(b.account);if(!DataCityRules.exit(now,b.lastIncome,food,RuralRules.demand(f,d.state.people),cash,quote(s,b.city,1,now))||CityOpportunities.viable(s,b))continue;b.closing=true;b.status="连续五日无收入且口粮不足，限量止损、寻找本地岗位";var site=d.state.sites.get(RuralSettlement.key(b.city,b.site));if(site!=null&&b.worker.equals(site.worker)){site.worker=null;site.vacantSince=now+1;}for(var h:CityData.get(s).require(b.city).housing.houses.values())h.workers.remove(b.worker);RuralSuccession.setRole(owner,RuralRules.Role.NONE);d.log(owner.name+"停止经营，货物和资金仍归原家庭");}d.setDirty();}
 static boolean urban(MinecraftServer s,UUID city){var t=get(s).state.towns.get(city);return t!=null&&t.urban;}
 static boolean managed(MinecraftServer s,UUID city){return get(s).state.towns.containsKey(city);}
 static boolean running(MinecraftServer s,UUID city){var d=get(s);return d.state.run.running&&d.state.towns.containsKey(city);}
 static int population(MinecraftServer s,UUID city){var d=RuralSettlement.get(s);return (int)d.state.people.values().stream().filter(p->!p.dead&&p.age!=RuralRules.Age.INFANT&&d.state.families.get(p.family)!=null&&city.equals(d.state.families.get(p.family).city)).count();}
 int target(MinecraftServer s,UUID city,int good){return Math.max(1,(int)Math.floor(population(s,city)*state.config.targets[good]+.5));}
 int base(UUID city,int good){return Math.max(1,(int)Math.floor(TradeRules.BASE[good]*(state.towns.get(city).urban?state.config.cityMultiplier:1)+.5));}
 Business head(UUID village){return state.businesses.values().stream().filter(b->b.city.equals(village)&&b.kind.equals("head")).findFirst().orElse(null);}
 /** Persist legacy staff assignments once; registration order must not choose every helper's employer. */
 boolean linkStaff(){
  var suppliers=state.businesses.values().stream().filter(b->b.kind.equals("supplier")).sorted(Comparator.comparing(b->b.id)).toList();
  var helpers=state.businesses.values().stream().filter(b->b.kind.equals("supplier_helper")).sorted(Comparator.comparing(b->b.id)).toList();
  var occupied=new HashSet<UUID>();boolean changed=false;
  for(var helper:helpers)if(helper.employer!=null){var employer=state.businesses.get(helper.employer);if(employer==null||!employer.kind.equals("supplier")||!employer.city.equals(helper.city)||!occupied.add(employer.id)){helper.employer=null;changed=true;}}
  record Pair(Business helper,Business employer,double distance){}
  var pairs=new ArrayList<Pair>();for(var helper:helpers)if(helper.employer==null)for(var employer:suppliers)if(helper.city.equals(employer.city)&&!employer.closing&&!occupied.contains(employer.id))pairs.add(new Pair(helper,employer,BlockPos.of(helper.site).distSqr(BlockPos.of(employer.site))));
  pairs.sort(Comparator.comparingDouble(Pair::distance).thenComparing(p->p.helper.id).thenComparing(p->p.employer.id));
  for(var pair:pairs)if(pair.helper.employer==null&&occupied.add(pair.employer.id)){pair.helper.employer=pair.employer.id;changed=true;}
  if(changed)setDirty();return changed;
 }
 Business employer(Business helper){linkStaff();return helper.employer==null?null:state.businesses.get(helper.employer);}
 Business helper(Business employer){linkStaff();return state.businesses.values().stream().filter(b->b.kind.equals("supplier_helper")&&employer.id.equals(b.employer)).findFirst().orElse(null);}
 List<Business> sellers(UUID city,int good){var list=new ArrayList<>(state.businesses.values().stream().filter(b->b.city.equals(city)).toList());var town=state.towns.get(city);if(town==null||!town.model)return list;UUID last=state.sellerCursor.get(city+":"+good);if(last!=null)for(int i=0;i<list.size();i++)if(list.get(i).id.equals(last)){Collections.rotate(list,-(i+1));break;}return list;}
 void soldFrom(Business b,int good){var town=state.towns.get(b.city);if(town!=null&&town.model)state.sellerCursor.put(b.city+":"+good,b.id);}
 Business liveHead(MinecraftServer s,UUID village){var h=head(village);if(h==null)return null;var p=RuralSettlement.get(s).state.people.get(h.worker);return p!=null&&!p.dead&&p.role==RuralRules.Role.MERCHANT?h:null;}
 int stock(MinecraftServer s,UUID city,int good){if(!state.towns.get(city).urban&&good<2){var h=liveHead(s,city);var p=h==null?null:RuralSettlement.get(s).state.people.get(h.worker);return (p==null?0:RuralMarket.count(RuralSettlement.get(s).stocks(p.family),good))+(good==0?RuralStalls.stock(s,city):0);}return state.businesses.values().stream().filter(b->b.city.equals(city)).mapToInt(b->b.listed[good].count).sum();}
 int quote(MinecraftServer s,UUID city,int good,long now){var t=state.towns.get(city);int price=TradeRules.quote(t.prices[good],base(city,good),stock(s,city,good),target(s,city,good),now);if(good==1&&t.model&&t.urban&&state.businesses.values().stream().anyMatch(b->b.city.equals(city)&&b.kind.equals("baker")&&b.listed[1].count>0&&usable(s,b)))price=Math.min(price,quote(s,city,0,now)+2);return price;}
 static int headQuote(MinecraftServer s,UUID city,int good,int base,int stock){var d=get(s);if(!d.state.towns.containsKey(city)||good>1)return -1;var p=d.state.towns.get(city).prices[good];long now=RuralSettlement.get(s).state.simulationTicks;stock=d.stock(s,city,good);TradeRules.observe(p,stock,d.target(s,city,good),now);return TradeRules.quote(base,stock,d.target(s,city,good),p.emptySince<0?0:now-p.emptySince,p.richSince<0?0:now-p.richSince)*10;}
 static boolean pay(MinecraftServer s,String from,String to,long amount,String type){return CityWorksFinance.transfer(CityEconomy.get(s),from,to,amount,RuralSettlement.get(s).state.simulationTicks,type);}
 long tax(MinecraftServer s,String from,UUID city,long silver,int rate,String key){if(silver<=0||rate<=0)return 0;var e=CityEconomy.get(s);int total=state.taxTails.getOrDefault(key,0)+(int)(silver*rate);long n=total/100;state.taxTails.put(key,total%100);if(n>0)CityEconomy.require(pay(s,from,CityEconomy.treasury(city),n,"TRADE_TAX"),"税款支付失败");CityCurrency.tax(s,city,n);return n;}
 static void wageTax(MinecraftServer s,UUID city,UUID worker,long gross){if(urban(s,city))get(s).tax(s,CityEconomy.person(worker),city,gross,4,"wage:"+worker);}
 int held(Business b){return Arrays.stream(b.stock).mapToInt(l->l.count).sum()+Arrays.stream(b.listed).mapToInt(l->l.count).sum();}
 boolean usable(MinecraftServer s,Business b){if(b.closing)return false;var d=RuralSettlement.get(s);var p=d.state.people.get(b.worker);if(p==null||p.dead||p.hunger()>=2)return false;var site=d.state.sites.get(RuralSettlement.key(b.city,b.site));return site!=null&&b.worker.equals(site.worker)&&RuralTools.available(s,site);}
 long familyMoney(MinecraftServer s,RuralRules.Family f){var e=CityEconomy.get(s);return f.members.stream().mapToLong(id->e.balance(CityEconomy.person(id))).sum();}
 static int mealTarget(RuralRules.Family f,RuralSettlement d){int need=RuralRules.demand(f,d.state.people);int recovery=RuralRules.members(f,d.state.people).stream().mapToInt(p->(int)Math.ceil(Math.max(0,p.maximum()-p.nourishment))).sum();var stores=d.stocks(f.id);return Math.max(need*2,need+recovery);}
 static long headReserve(MinecraftServer s,UUID village){var t=get(s);if(!t.state.towns.containsKey(village)||t.state.towns.get(village).urban)return 0;var d=RuralSettlement.get(s);var h=t.liveHead(s,village);if(h==null)return 0;var p=d.state.people.get(h.worker);int farmers=(int)d.state.people.values().stream().filter(v->!v.dead&&v.role==RuralRules.Role.FARMER&&v.family!=null&&village.equals(d.state.families.get(v.family).city)).count();int needed=Math.min(RuralRules.capacity(d.stocks(p.family)),Math.min(farmers*20,Math.max(0,t.target(s,village,0)-t.stock(s,village,0))));int price=Math.max(1,headQuote(s,village,0,RuralMarket.baseBuy(0),t.stock(s,village,0))/10);return needed*(long)price+CityWorksFinance.protectedFood(s,p.id);}
 void shopMeat(MinecraftServer s,RuralRules.Person p,RuralRules.Family f,long spare){if(state.towns.get(f.city).urban){if(CityCurrency.model(s,f.city)&&s.overworld().random.nextDouble()<.65)CityRoute.buyMeat(s,f,1,spare/2,FamilyLivelihood.processor(s,f));return;}if(s.overworld().random.nextDouble()>=.65)return;var d=RuralSettlement.get(s);var h=liveHead(s,f.city);if(h==null||f.members.contains(h.worker)||!DataCityRules.improvementRoom(RuralRules.count(d.stocks(f.id),false)+RuralRules.count(d.stocks(f.id),true),RuralRules.capacity(d.stocks(f.id)),RuralRules.demand(f,d.state.people),RuralRules.count(d.stocks(f.id),false)))return;boolean cook=!d.workers(f,RuralRules.Role.COOK).isEmpty();var source=d.stocks(d.state.people.get(h.worker).family);int start=s.overworld().random.nextInt(5);for(int i=0;i<5;i++){int type=(start+i)%5;boolean cooked=!cook||RuralMeat.count(source,false,type)==0;int q=RuralFoodAccess.retail(d,d.state.people.get(h.worker),type+(cooked?7:2),source);if(spare<q*1.5||RuralMeat.count(source,cooked,type)==0)continue;int paid=improvementTrade(s,p,f,h,type,cooked,q);if(paid>=0){state.run.foodImprovementUnits++;state.run.foodImprovementSilver+=paid;d.state.meatBought++;d.state.tradedSilver+=paid;d.audit(f.city).tradeSilver+=paid;state.run.consumerSales++;}break;}}
 int improvementTrade(MinecraftServer s,RuralRules.Person buyer,RuralRules.Family f,Business h,int type,boolean cooked,int price){var d=RuralSettlement.get(s);var target=d.stocks(f.id);var source=d.stocks(d.state.people.get(h.worker).family);if(RuralCooking.available(d,d.state.people.get(h.worker),type+(cooked?7:2),source)<=0)return -1;boolean swap=RuralRules.capacity(target)==0;int credit=0;if(swap){if(!DataCityRules.improvementRoom(RuralRules.count(target,false)+RuralRules.count(target,true),0,RuralRules.demand(f,d.state.people),RuralRules.count(target,false)))return -1;credit=Math.max(1,(headQuote(s,f.city,0,RuralMarket.baseBuy(0),RuralRules.count(source,false))+5)/10);if(credit>price)return -1;}int paid=price-credit;if(!pay(s,CityEconomy.person(buyer.id),h.account,paid,swap?"IMPROVEMENT_FOOD_SWAP":"IMPROVEMENT_FOOD"))return -1;var grain=swap?FoodMoves.remove(target,0,1):FoodAge.Portion.FRESH;var meat=FoodMoves.remove(source,type+(cooked?7:2),1);CityEconomy.require(meat.count()==1&&FoodMoves.add(target,type+(cooked?7:2),1,meat.age())==1,"改善食品交割失败");if(swap){CityEconomy.require(grain.count()==1&&FoodMoves.add(source,0,1,grain.age())==1,"换货粮食交割失败");state.run.foodBarterWheat++;}return paid;}
 boolean familyPay(MinecraftServer s,RuralRules.Family f,String recipient,long amount){if(amount<0||familyMoney(s,f)<amount)return false;long left=amount;for(var id:f.members){long n=Math.min(left,CityEconomy.get(s).balance(CityEconomy.person(id)));if(n>0)CityEconomy.require(pay(s,CityEconomy.person(id),recipient,n,"FAMILY_PURCHASE"),"家庭付款失败");left-=n;if(left==0)break;}return true;}
 void profit(MinecraftServer s,Business b,int revenue,long costCents){b.lastIncome=RuralSettlement.get(s).state.simulationTicks;long margin=revenue*100L-costCents;if(margin<0){b.expenseCents-=margin;return;}long expense=Math.min(margin,b.expenseCents);b.expenseCents-=expense;margin-=expense;b.profitCents+=margin;long whole=b.profitCents/100;b.profitCents%=100;if(urban(s,b.city)&&whole>0)b.tax+=tax(s,b.account,b.city,whole,b.kind.equals("procurement")?15:8,"profit:"+b.id);}
 int buyMarket(MinecraftServer s,RuralRules.Family family,UUID city,int good,int wanted,boolean privateFood){int done=0;var d=RuralSettlement.get(s);for(var b:sellers(city,good)){if(wanted<=0)continue;int price=quote(s,city,good,d.state.simulationTicks);int n=(int)Math.min(Math.min(wanted,b.listed[good].count),familyMoney(s,family)/price);if(privateFood)n=Math.min(n,RuralRules.capacity(d.stocks(family.id)));if(n<=0)continue;long cost=b.listed[good].cents*n/b.listed[good].count;if(!familyPay(s,family,b.account,(long)n*price))continue;b.listed[good].take(n);if(privateFood)CityEconomy.require(FoodMoves.add(d.stocks(family.id),good,n,b.listed[good].removedAge.age())==n,"口粮交割失败");b.sales+=(long)n*price;b.sold[good]+=n;profit(s,b,n*price,cost);soldFrom(b,good);done+=n;wanted-=n;}return done;}
 void list(MinecraftServer s,Business b,long now){if((!b.closing&&!usable(s,b))||!WorkHours.active(s,CityData.get(s).require(b.city),b.worker))return;for(int g=0;g<4;g++){var lot=b.stock[g];if(lot.count==0){b.listing[g]=false;b.batch[g]=0;continue;}int q=quote(s,b.city,g,now);if(b.kind.equals("procurement")&&!b.closing){if(!b.listing[g]&&q>lot.unit()){b.listing[g]=true;b.batch[g]=0;}if(q<=lot.unit()){b.listing[g]=false;b.status="市价不高于成本，暂存";continue;}if(!b.listing[g])continue;}int cap=g<2?192:64;int n=Math.min(lot.count,Math.min(g<2?state.config.grainStep:state.config.consumerStep,cap-b.batch[g]));if(b.closing)n=Math.min(n,liquidate(s,b,g));if(n>0){TradeRules.move(lot,b.listed[g],n);b.batch[g]+=n;}if(b.batch[g]>=cap){b.batch[g]=0;b.listing[g]=false;}}}
 int liquidate(MinecraftServer s,Business b,int good){var d=RuralSettlement.get(s);var p=d.state.people.get(b.owner);if(p==null||p.dead)return 0;var f=d.state.families.get(p.family);if(f==null)return 0;long needed=Math.max(0,mealTarget(f,d)-RuralRules.count(d.stocks(f.id),true))*(long)quote(s,b.city,1,d.state.simulationTicks)-familyMoney(s,f)-CityEconomy.get(s).balance(b.account);for(int g=0;g<4;g++)needed-=b.listed[g].count*(long)quote(s,b.city,g,d.state.simulationTicks);int q=quote(s,b.city,good,d.state.simulationTicks);return (int)Math.clamp((needed+q-1)/q,0,192);}
 void withdraw(MinecraftServer s,Business b){if(!urban(s,b.city)||!Set.of("procurement","baker","supplier").contains(b.kind))return;long reserve=b.kind.equals("baker")?100:200;long free=CityEconomy.get(s).balance(b.account)-reserve;if(free>0)pay(s,b.account,CityEconomy.person(b.owner==null?b.worker:b.owner),free,"OWNER_DRAW");}
 void travel(MinecraftServer s,Business b,long now,long day){if(CityCurrency.model(s,b.city)){CityRoute.travel(s,b,now,day);return;}if(CityRiskLab.tradeBlocked(s,b.city)||!b.kind.equals("procurement")||!usable(s,b)||!WorkHours.active(s,CityData.get(s).require(b.city),b.worker))return;var d=RuralSettlement.get(s);var e=CityEconomy.get(s);var city=CityData.get(s).require(b.city);UUID village=state.towns.get(b.city).partner==null?state.run.village:state.towns.get(b.city).partner;var h=liveHead(s,village);if(h==null)return;
  if(b.phase==0){if(b.departedDay==day||Math.floorMod(d.state.simulationDay,24000)>1200||held(b)>=900)return;b.perception=1+(s.overworld().random.nextDouble()*2-1)*state.config.perceptionError;int villagePrice=quote(s,village,0,now);b.planned=TradeRules.plan(stock(s,b.city,0),target(s,b.city,0),base(b.city,0),villagePrice,b.perception,TradeRules.capacity(b.cargo),e.balance(b.account)-40,state.towns.get(b.city).prices[0].richSince<0?0:now-state.towns.get(b.city).prices[0].richSince);if(b.planned==0){b.status="出发估价无利可图";return;}
   for(int g=2;g<4;g++)for(int cargoUnit=0;cargoUnit<8;cargoUnit++){Business supplier=null;for(var candidate:sellers(b.city,g))if(candidate.kind.equals("supplier")&&(!CityCurrency.model(s,b.city)||candidate.listed[g].count>0)){supplier=candidate;break;}if(supplier==null||supplier.listed[g].count==0)continue;int q=quote(s,b.city,g,now);if(e.balance(b.account)<q+40)continue;if(pay(s,b.account,supplier.account,q,"OUTBOUND_GOODS")){long cost=supplier.listed[g].take(1);b.cargo[g].add(1,q*100L);b.purchases+=q;b.bought[g]++;supplier.sales+=q;supplier.sold[g]++;profit(s,supplier,q,cost);soldFrom(supplier,g);}}
   b.phase=1;b.arrive=now+Math.round(state.config.travelTicks/FamilyLivelihood.workFactor(s,d.state.people.get(b.worker)));b.departedDay=day;b.status="前往农村";
  }else if(now>=b.arrive&&b.phase==1){var hp=d.state.people.get(h.worker);var hf=d.state.families.get(hp.family);var stocks=d.stocks(hf.id);int protect=RuralMarket.reserve(d,d.state.families.values().stream().filter(f->f.city.equals(village)).toList(),hf);int available=Math.max(0,RuralRules.count(stocks,false)-Math.max(0,protect-RuralRules.count(stocks,true)));int price=quote(s,village,0,now);int n=(int)Math.min(Math.min(Math.min(b.planned,192),available),Math.max(0,e.balance(b.account)-40)/price);n=Math.min(n,1000-held(b));if(n>0&&pay(s,b.account,h.account,(long)n*price,"VILLAGE_GRAIN_PURCHASE")){RuralRules.take(stocks,false,n);b.cargo[0].add(n,n*price*100L);b.purchases+=(long)n*price;b.bought[0]+=n;state.run.grainTrades+=n;}else b.emptyTrips++;
   for(int g=2;g<4;g++)for(int cargoUnit=0;cargoUnit<8;cargoUnit++){int q=Math.max(1,(int)Math.floor(quote(s,village,g,now)*.95+.5));if(b.cargo[g].count>0&&q>=b.cargo[g].unit()&&e.balance(h.account)-headReserve(s,village)>=q&&held(h)<1000&&pay(s,h.account,b.account,q,"VILLAGE_CONSUMER_IMPORT")){long cost=b.cargo[g].take(1);h.stock[g].add(1,q*100L);h.purchases+=q;h.bought[g]++;b.sales+=q;b.sold[g]++;profit(s,b,q,cost);}}
   b.phase=2;b.arrive=now+Math.round(state.config.travelTicks/FamilyLivelihood.workFactor(s,d.state.people.get(b.worker)));b.status="返回城市";
  }else if(now>=b.arrive&&b.phase==2){for(int g=0;g<4;g++)TradeRules.move(b.cargo[g],b.stock[g],b.cargo[g].count);b.phase=0;b.trips++;b.status="回城分批上架";withdraw(s,b);}
 }
 void wage(MinecraftServer s,Business b,int count){int gross=count*4;if(!pay(s,b.account,CityEconomy.person(b.worker),gross,"PRIVATE_WORK_WAGE")){b.status="经营款不足，停工";return;}FamilyLivelihood.paid(s,b.worker);b.wages+=gross;b.expenseCents+=gross*100L;wageTax(s,b.city,b.worker,gross);}
 void production(MinecraftServer s,Business b,long now){if(!urban(s,b.city)||!usable(s,b)||!WorkHours.active(s,CityData.get(s).require(b.city),b.worker))return;var e=CityEconomy.get(s);boolean self=b.owner!=null&&b.owner.equals(b.worker);if(e.balance(b.account)<4&&!(b.kind.equals("baker")&&self))return;
  if(b.kind.equals("baker")){if(CityCurrency.model(s,b.city)&&self)CityRoute.capital(s,b,100);if(CityCurrency.model(s,b.city)&&b.stock[0].count==0&&self){var worker=RuralSettlement.get(s).state.people.get(b.worker);var family=RuralSettlement.get(s).state.families.get(worker.family);var stores=RuralSettlement.get(s).stocks(family.id);int excess=Math.max(0,RuralRules.count(stores,false)-DataCityRules.foodReserve(RuralRules.demand(family,RuralSettlement.get(s).state.people),3));int n=Math.min(20,excess);if(n>0){var portion=FoodMoves.remove(stores,0,n);b.stock[0].receive(n,n*quote(s,b.city,0,now)*100L,portion);CityEconomy.get(s).log(now,"OWNER_RAW_MATERIAL",CityEconomy.person(b.worker),b.account,0,"自有家庭余粮入股x"+n+"，保留三日家庭主粮，不增加数量或现金");}}if(CityCurrency.model(s,b.city)){CityBaking.plan(s,b.city);CityBakeService.earn(s,b,now);CityBakeService.serve(s,b);if(b.breadRemaining<=0){b.status="本日按需加工计划已满足";return;}}int q=quote(s,b.city,0,now),bread=quote(s,b.city,1,now);if(bread*20<q*20+4){b.status="面包报价不足以覆盖原料与人工";return;}int batch=CityCurrency.model(s,b.city)?Math.min(Math.min(20,b.breadRemaining),CityBakeService.retailDemand(s,b.city)):20;if(batch<=0)return;if(b.stock[0].count<batch){for(var seller:sellers(b.city,0)){if(seller==b||seller.listed[0].count==0)continue;int n=(int)Math.min(Math.min(batch-b.stock[0].count,seller.listed[0].count),Math.max(0,e.balance(b.account)-4)/q);if(n>0&&pay(s,b.account,seller.account,(long)n*q,"BAKERY_WHEAT")){long cost=seller.listed[0].take(n);b.stock[0].receive(n,n*q*100L,seller.listed[0].removedAge);b.purchases+=(long)n*q;b.bought[0]+=n;seller.sales+=(long)n*q;seller.sold[0]+=n;profit(s,seller,n*q,cost);soldFrom(seller,0);}}}if(b.stock[0].count==0||b.stock[1].count+b.listed[1].count>=80)return;var p=RuralSettlement.get(s).state.people.get(b.worker);if(!CityCurrency.model(s,b.city))CityBakeService.earn(s,b,now);int n=Math.min(batch,Math.min((int)b.outputCredit,b.stock[0].count));if(n<=0)return;if(e.balance(b.account)<4&&!self)return;b.outputCredit-=n;if(e.balance(b.account)>=4)wage(s,b,1);if(CityCurrency.model(s,b.city))b.breadRemaining-=n;long cost=b.stock[0].take(n);b.stock[1].add(n,cost);b.status="批量烘焙";
  }else if(b.kind.equals("supplier")){var helper=helper(b);boolean second=helper!=null&&usable(s,helper)&&WorkHours.active(s,CityData.get(s).require(helper.city),helper.worker);var p=RuralSettlement.get(s).state.people.get(b.worker);b.outputCredit+=RuralRules.efficiency(p.trainedHours)*FamilyLivelihood.workFactor(s,p)*CityWorks.workerEfficiency(s,CityData.get(s).require(b.city),p.id)/10000.0;if(second){var hp=RuralSettlement.get(s).state.people.get(helper.worker);b.outputCredit+=RuralRules.efficiency(hp.trainedHours)*FamilyLivelihood.workFactor(s,hp)*CityWorks.workerEfficiency(s,CityData.get(s).require(b.city),hp.id)/10000.0;}b.outputCredit=Math.min(2,b.outputCredit);int workers=Math.min(second?2:1,(int)b.outputCredit);int[] output=TradeRules.supplierOutput(workers,Math.floorDiv(RuralSettlement.get(s).state.simulationDay,3000),state.config.supplierCap-b.stock[2].count-b.listed[2].count,state.config.supplierCap-b.stock[3].count-b.listed[3].count);int actual=output[0]+output[1];if(actual==0)return;int earned=quote(s,b.city,2,now)*output[0]+quote(s,b.city,3,now)*output[1];if(earned<actual*4){b.status="报价不足覆盖工资，等待去库存";return;}if(e.balance(b.account)<actual*4){b.status="经营款不足，停工";return;}b.outputCredit-=actual;wage(s,b,1);if(actual==2&&second){pay(s,b.account,CityEconomy.person(helper.worker),4,"PRIVATE_WORK_WAGE");FamilyLivelihood.paid(s,helper.worker);b.wages+=4;b.expenseCents+=400;wageTax(s,b.city,helper.worker,4);}for(int g=2;g<4;g++)if(output[g-2]>0){b.stock[g].add(output[g-2],0);state.run.supplierInput+=output[g-2];}b.status="测试消费品供货（已记输入）";
  }
 }
 static int goodsCount(MinecraftServer s,RuralRules.Family family,int good){var d=RuralSettlement.get(s);var l=CityEconomy.level(s,CityData.get(s).require(family.city));int n=0;for(var b:d.state.boxes.values())if(b.present&&family.id.equals(b.stock.family))for(var stack:NpcStorage.projected(l,b))if(CityEconomy.plain(stack,CityEconomy.item(TradeRules.IDS[good])))n+=stack.getCount();return n;}
 static boolean privateGoods(MinecraftServer s,RuralRules.Family f,int good,int delta){var d=RuralSettlement.get(s);var l=CityEconomy.level(s,CityData.get(s).require(f.city));for(var box:d.state.boxes.values()){if(!box.present||!f.id.equals(box.stock.family))continue;var items=NpcStorage.projected(l,box);for(int i=0;i<items.size();i++){var item=items.get(i);if(delta>0&&(item.isEmpty()||CityEconomy.plain(item,CityEconomy.item(TradeRules.IDS[good]))&&item.getCount()<64)){if(item.isEmpty())items.set(i,new ItemStack(CityEconomy.item(TradeRules.IDS[good]),1));else item.grow(1);writeBox(l,box,items);return true;}if(delta<0&&CityEconomy.plain(item,CityEconomy.item(TradeRules.IDS[good]))){item.shrink(1);writeBox(l,box,items);return true;}}}return false;}
 static void writeBox(net.minecraft.server.level.ServerLevel l,RuralSettlement.Box box,List<ItemStack> items){box.slots.clear();box.stock.ordinarySlots=0;for(var item:items){box.slots.add(item.isEmpty()?"":item.save(l.registryAccess()).toString());if(!item.isEmpty()&&NpcStorage.food(item)<0)box.stock.ordinarySlots++;}RuralSettlement.get(l.getServer()).setDirty();var pos=BlockPos.of(box.pos);if(l.hasChunkAt(pos)&&l.getBlockEntity(pos) instanceof RuralBlocks.Link link&&link.inventory!=null)link.inventory=NpcStorage.projected(l,box);}
 void shop(MinecraftServer s,UUID city,long day){var d=RuralSettlement.get(s);for(var p:d.state.people.values()){if(p.dead||p.hunger()>0||p.age.ordinal()<2||!city.equals(d.state.families.get(p.family).city)||Objects.equals(state.shoppingDay.get(p.id),day))continue;state.shoppingDay.put(p.id,day);var f=d.state.families.get(p.family);var stores=d.stocks(f.id);int need=RuralRules.demand(f,d.state.people);if(RuralRules.count(stores,false)+RuralRules.count(stores,true)<need*2)continue;long spare=FamilyBudget.spare(s,f,p.id);if(spare<=0||s.overworld().random.nextDouble()>=.5)continue;long beforeLuxury=familyMoney(s,f),beforeOwned=FamilyBudget.owned(s,f);shopMeat(s,p,f,spare);FamilyBudget.spent(s,f,beforeLuxury-familyMoney(s,f),beforeOwned-FamilyBudget.owned(s,f));spare=FamilyBudget.spare(s,f,p.id);if(s.overworld().random.nextDouble()>=.5)continue;int g=2+s.overworld().random.nextInt(2),q=quote(s,city,g,d.state.simulationTicks);if(spare<q*1.5)continue;for(var seller:sellers(city,g))if(seller.listed[g].count>0){if(!privateGoods(s,f,g,1))break;long beforeGoods=FamilyBudget.owned(s,f);if(!pay(s,CityEconomy.person(p.id),seller.account,q,"CONSUMER_PURCHASE")){privateGoods(s,f,g,-1);break;}FamilyBudget.spent(s,f,q,beforeGoods-FamilyBudget.owned(s,f));long cost=seller.listed[g].take(1);seller.sales+=q;seller.sold[g]++;profit(s,seller,q,cost);soldFrom(seller,g);state.run.consumerSales++;break;}}}
 void emergencySale(MinecraftServer s,RuralRules.Family f){var d=RuralSettlement.get(s);int missing=Math.max(0,RuralRules.demand(f,d.state.people)-RuralRules.count(d.stocks(f.id),true));if(missing==0)return;int foodPrice=quote(s,f.city,1,d.state.simulationTicks);if(familyMoney(s,f)>=missing*foodPrice)return;for(int g=2;g<4;g++){if(goodsCount(s,f,g)==0)continue;var buyer=state.businesses.values().stream().filter(b->b.city.equals(f.city)&&(b.kind.equals("head")||b.kind.equals("supplier"))).filter(b->{var agent=d.state.people.get(b.worker);return agent!=null&&!agent.dead;}).findFirst().orElse(null);if(buyer==null)continue;int q=quote(s,f.city,g,d.state.simulationTicks);if(CityEconomy.get(s).balance(buyer.account)>=q+64&&privateGoods(s,f,g,-1)){pay(s,buyer.account,CityEconomy.person(f.members.getFirst()),q,"EMERGENCY_RESALE");buyer.stock[g].add(1,q*100L);for(var id:f.members)state.shoppingDay.put(id,Math.floorDiv(d.state.simulationDay,24000));return;}int breads=q/foodPrice;if(breads>0&&q%foodPrice==0&&buyer.listed[1].count>=breads&&RuralRules.capacity(d.stocks(f.id))>=breads&&privateGoods(s,f,g,-1)){buyer.listed[1].take(breads);FoodMoves.add(d.stocks(f.id),1,breads,buyer.listed[1].removedAge.age());buyer.stock[g].add(1,q*100L);state.run.barter++;return;}}}
 void sellEmergencyWheat(MinecraftServer s,RuralRules.Family f){var d=RuralSettlement.get(s);int missing=Math.max(0,mealTarget(f,d)-RuralRules.count(d.stocks(f.id),true));long shortfall=missing*(long)quote(s,f.city,1,d.state.simulationTicks)-familyMoney(s,f);if(shortfall<=0)return;int q=quote(s,f.city,0,d.state.simulationTicks);for(var b:state.businesses.values())if(b.city.equals(f.city)&&b.kind.equals("baker")&&usable(s,b)){int n=(int)Math.min(Math.min((shortfall+q-1)/q,RuralRules.count(d.stocks(f.id),false)),Math.min(40-b.stock[0].count,Math.max(0,CityEconomy.get(s).balance(b.account)-64)/q));if(n>0&&pay(s,b.account,CityEconomy.person(f.members.getFirst()),n*(long)q,"EMERGENCY_WHEAT_SALE")){var portion=FoodMoves.remove(d.stocks(f.id),0,n);b.stock[0].receive(n,n*q*100L,portion);b.purchases+=(long)n*q;b.bought[0]+=n;}break;}}
 void supportOwnerMeal(MinecraftServer s,RuralRules.Family f){var d=RuralSettlement.get(s);int missing=Math.max(0,mealTarget(f,d)-RuralRules.count(d.stocks(f.id),true));long needed=missing*(long)quote(s,f.city,1,d.state.simulationTicks)-familyMoney(s,f);if(needed<=0)return;for(var b:state.businesses.values()){if(!b.city.equals(f.city)||!f.members.contains(b.owner==null?b.worker:b.owner)||!Set.of("procurement","supplier","baker").contains(b.kind)||!b.account.startsWith("trade:"))continue;long n=Math.min(needed,CityEconomy.get(s).balance(b.account));if(n>0&&pay(s,b.account,CityEconomy.person(b.owner==null?b.worker:b.owner),n,"OWNER_NEXT_MEAL"))needed-=n;if(needed<=0)break;}}
 void urbanCycle(MinecraftServer s,CityData.City city,boolean meal){var d=RuralSettlement.get(s);CityRelief.track(s,city.id);for(var f:d.state.families.values()){if(!f.city.equals(city.id))continue;var stores=d.stocks(f.id);int need=RuralRules.demand(f,d.state.people);for(var p:RuralRules.members(f,d.state.people))if(p.role==RuralRules.Role.FARMER){p.cropTicks+=p.workingTicks;p.productionCredit+=28*CityRiskLab.cropFactor(s,city.id)*RuralRules.efficiency(p.trainedHours)*FamilyLivelihood.workFactor(s,p)*CityWorks.workerEfficiency(s,city,p.id)/10000.0*p.workingTicks/36000.0;if(p.cropTicks>=36000){p.cropTicks%=36000;int n=(int)p.productionCredit;p.productionCredit-=n;p.pendingAge.ensure(p.pendingWheat);p.pendingAge.add(n,0);p.pendingWheat+=n;state.run.urbanHarvest+=n;}int kept=Math.min(p.pendingWheat,RuralRules.capacity(stores));var keptPart=RuralStalls.take(p,kept);FoodMoves.add(stores,0,kept,keptPart.age());var farm=state.businesses.values().stream().filter(b->b.worker.equals(p.id)&&b.kind.equals("urban_farmer")).findFirst().orElse(null);if(farm!=null&&p.pendingWheat>0&&held(farm)<1000){int n=Math.min(p.pendingWheat,1000-held(farm));var extra=RuralStalls.take(p,n);farm.stock[0].receive(n,0,extra);}}
   supportOwnerMeal(s,f);OwnerFood.draw(s,f);var choice=state.households.get(f.id);if(FamilyLivelihood.processor(s,f)&&choice!=null&&choice.preferPrepared)buyMarket(s,f,city.id,1,Math.max(0,mealTarget(f,d)-RuralCooking.ready(stores)),true);if(FamilyLivelihood.processor(s,f)){int raw=Math.max(0,mealTarget(f,d)-RuralRules.count(stores,true)-RuralRules.count(stores,false));raw=(int)Math.min(raw,Math.max(0,familyMoney(s,f)-FamilyBudget.processing(s,f))/quote(s,city.id,0,d.state.simulationTicks));buyMarket(s,f,city.id,0,raw,true);FamilyLivelihood.cook(s,f);}else sellEmergencyWheat(s,f);emergencySale(s,f);int wanted=Math.max(0,(FamilyLivelihood.processor(s,f)?(meal?need:0):mealTarget(f,d))-RuralRules.count(stores,true));buyMarket(s,f,city.id,1,wanted,true);if(CityCurrency.model(s,city.id))CityRoute.emergency(s,f);if(meal){CityRelief.give(s,f);int before=RuralRules.count(stores,true),meatBefore=RuralMeat.total(stores);RuralRules.meal(RuralRules.members(f,d.state.people),stores);int eaten=before-RuralRules.count(stores,true);state.run.urbanEaten+=eaten;d.audit(city.id).breadEaten+=eaten;d.audit(city.id).meatEaten+=meatBefore-RuralMeat.total(stores);}for(var p:RuralRules.members(f,d.state.people)){p.stageTicks+=1200;p.workingTicks=0;}}
 }
 static void beforeRural(MinecraftServer s,CityData.City city){var t=get(s);if(!t.state.towns.containsKey(city.id)||t.state.towns.get(city.id).urban)return;var h=t.liveHead(s,city.id);if(h!=null){var p=RuralSettlement.get(s).state.people.get(h.worker);p.wheatPrice=t.quote(s,city.id,0,RuralSettlement.get(s).state.simulationTicks);p.breadPrice=t.quote(s,city.id,1,RuralSettlement.get(s).state.simulationTicks);}for(var f:RuralSettlement.get(s).state.families.values())if(city.id.equals(f.city))t.emergencySale(s,f);}
 static void step(MinecraftServer s){var t=get(s);if(!t.state.run.running&&t.state.towns.keySet().stream().noneMatch(id->RuralSettlement.active(s,id)))return;long start=System.nanoTime();var d=RuralSettlement.get(s);long now=d.state.simulationTicks;FoodDecay.step(s,now);if(now<t.state.nextStep)return;t.state.nextStep=now+t.state.config.listingTicks;long day=Math.floorDiv(d.state.simulationDay,24000),segment=Math.floorDiv(d.state.simulationDay,3000);boolean produce=segment!=t.state.lastSegment;t.state.lastSegment=segment;
  for(var town:t.state.towns.values())for(int g=0;g<4;g++)t.quote(s,town.city,g,now);
  for(var town:t.state.towns.values())if(RuralSettlement.active(s,town.city))FamilyLivelihood.daily(s,CityData.get(s).require(town.city));CityMaterialImports.step(s,now);t.exits(s,now);for(var b:t.state.businesses.values()){if(!RuralSettlement.active(s,b.city))continue;var site=d.state.sites.get(RuralSettlement.key(b.city,b.site));if(site!=null){if(b.kind.equals("urban_farmer"))site.kind="farmer";if(b.kind.equals("supplier_helper"))site.kind="supplier";}if(produce)t.production(s,b,now);t.travel(s,b,now,day);if(!b.kind.equals("baker")||b.stock[1].count>0){if(b.kind.equals("baker")){var grain=b.stock[0];b.stock[0]=new TradeRules.Lot();t.list(s,b,now);b.stock[0]=grain;}else t.list(s,b,now);}if(produce)t.withdraw(s,b);}
  for(var town:t.state.towns.values())if(RuralSettlement.active(s,town.city)){CityRelief.track(s,town.city);if(produce)CityRelief.purchase(s,town.city);}
  if(Math.floorMod(d.state.simulationDay,24000)>=6000&&Math.floorMod(d.state.simulationDay,24000)<12000)for(var town:t.state.towns.values())if(RuralSettlement.active(s,town.city))t.shop(s,town.city,day);
  t.state.run.maxStepMs=Math.max(t.state.run.maxStepMs,(System.nanoTime()-start)/1e6);if(t.state.run.running&&now-t.state.run.lastSample>=24000){t.state.run.lastSample=now;t.sample(s);t.write(s);}if(t.state.run.running&&now-t.state.run.startClock>=30L*24000){t.state.run.running=false;t.state.run.done=true;t.state.run.endClock=now;t.state.run.endedAt=java.time.OffsetDateTime.now().toString();t.sample(s);for(var town:t.state.towns.values()){d.state.enabled.remove(town.city);CityData.get(s).require(town.city).works.enabled=false;CityData.get(s).require(town.city).housing.testSupply=false;}t.write(s);}t.setDirty();
 }
 long money(MinecraftServer s){var e=CityEconomy.get(s);var accounts=new HashSet<String>();for(var town:state.towns.values()){accounts.add(CityEconomy.treasury(town.city));accounts.add("market:"+town.city);var c=CityData.get(s).require(town.city);for(var id:c.residents){accounts.add(CityEconomy.person(id));accounts.add("works:"+town.city+":"+id);}}for(var b:state.businesses.values())accounts.add(b.account);return accounts.stream().mapToLong(e::balance).sum();}
 long grain(MinecraftServer s){var d=RuralSettlement.get(s);long n=0;for(var b:d.state.boxes.values())if(b.present&&state.towns.containsKey(b.city))n+=b.stock.wheat+b.stock.bread;for(var p:d.state.people.values())if(p.family!=null&&state.towns.containsKey(d.state.families.get(p.family).city))n+=p.pendingWheat;for(var b:state.businesses.values())for(var lots:List.of(b.stock,b.listed,b.cargo))n+=lots[0].count+lots[1].count;for(var town:state.towns.values()){var c=CityData.get(s).require(town.city);n+=c.works.resources.getOrDefault("minecraft:bread",0)+c.works.resources.getOrDefault("minecraft:wheat",0);for(var m:c.housing.market.entrySet())if(m.getKey().equals("minecraft:wheat")||m.getKey().equals("minecraft:bread"))n+=m.getValue().stock;}return n;}
 long goods(MinecraftServer s){long n=0;var d=RuralSettlement.get(s);for(var f:d.state.families.values())if(state.towns.containsKey(f.city))for(int g=2;g<4;g++)n+=goodsCount(s,f,g);for(var b:state.businesses.values())for(var lots:List.of(b.stock,b.listed,b.cargo))n+=lots[2].count+lots[3].count;return n;}
 long harvested(MinecraftServer s){var d=RuralSettlement.get(s);return state.towns.keySet().stream().mapToLong(id->d.audit(id).wheatMatured).sum()+state.run.urbanHarvest;}
 long meat(MinecraftServer s){var d=RuralSettlement.get(s);long publicStock=0;for(var town:state.towns.values()){var c=CityData.get(s).require(town.city);for(int g=2;g<12;g++){String id=net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(NpcStorage.item(g)).toString();publicStock+=c.works.resources.getOrDefault(id,0);var material=c.housing.market.get(id);if(material!=null)publicStock+=material.stock;}}return publicStock+ d.state.boxes.values().stream().filter(b->b.present&&state.towns.containsKey(b.city)).mapToLong(b->RuralMeat.total(List.of(b.stock))).sum()+state.businesses.values().stream().mapToLong(b->Arrays.stream(b.meatCargo).mapToLong(l->l.count).sum()+Arrays.stream(b.meatListed).mapToLong(l->l.count).sum()).sum();}
 long meatProduced(MinecraftServer s){var d=RuralSettlement.get(s);return d.state.people.values().stream().filter(p->p.family!=null&&d.state.families.containsKey(p.family)&&state.towns.containsKey(d.state.families.get(p.family).city)).mapToLong(p->p.meatProduced).sum();}
 long meatEaten(MinecraftServer s){var d=RuralSettlement.get(s);long consumed=state.towns.keySet().stream().mapToLong(id->d.audit(id).meatEaten).sum();for(var id:state.towns.keySet())for(var item:RuralMeat.COOKED)consumed+=CityData.get(s).require(id).works.materialsConsumed.getOrDefault(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item).toString(),0L);return consumed;}
 long eaten(MinecraftServer s){var d=RuralSettlement.get(s);long n=state.towns.keySet().stream().mapToLong(id->d.audit(id).breadEaten).sum();for(var id:state.towns.keySet())n+=CityData.get(s).require(id).works.materialsConsumed.getOrDefault("minecraft:bread",0L);return n;}
 void sample(MinecraftServer s){var r=state.run;var d=RuralSettlement.get(s);Map<String,Object> row=new LinkedHashMap<>();row.put("gameTick",s.overworld().getGameTime());row.put("simulationTicks",d.state.simulationTicks);row.put("elapsedDays",(d.state.simulationTicks-r.startClock)/24000.0);row.put("money",money(s));long migration=state.towns.keySet().stream().mapToLong(id->CityData.get(s).require(id).works.migrantSilver).sum()-r.initialMigrationSilver;row.put("migrationSilver",migration);row.put("moneyError",money(s)-r.initialMoney-migration);row.put("grain",grain(s));row.put("grainError",grain(s)-(r.initialGrain+harvested(s)-r.initialHarvest-(eaten(s)-r.initialBreadEaten)));row.put("meat",meat(s));row.put("meatError",meat(s)-(r.initialMeat+meatProduced(s)-r.initialMeatProduced-(meatEaten(s)-r.initialMeatEaten)));row.put("goods",goods(s));row.put("goodsError",goods(s)-r.initialGoods-r.supplierInput);row.put("initialDeaths",r.initialDeaths);row.put("deaths",d.state.people.values().stream().filter(p->p.dead&&state.towns.containsKey(d.state.families.get(p.family).city)).count());row.put("hungry",d.state.people.values().stream().filter(p->!p.dead&&p.hunger()>0&&state.towns.containsKey(d.state.families.get(p.family).city)).count());var balances=new LinkedHashMap<String,Long>();for(var b:state.businesses.values())balances.put(b.kind+":"+b.worker.toString().substring(0,6),CityEconomy.get(s).balance(b.account));row.put("businessBalances",balances);r.samples.add(row);if(r.samples.size()>64)r.samples.removeFirst();r.checks.put("moneyConserved",r.samples.stream().allMatch(v->((Number)v.get("moneyError")).longValue()==0));r.checks.put("grainConserved",r.samples.stream().allMatch(v->((Number)v.get("grainError")).longValue()==0));r.checks.put("consumerGoodsConserved",r.samples.stream().allMatch(v->((Number)v.get("goodsError")).longValue()==0));r.checks.put("meatConserved",r.samples.stream().allMatch(v->((Number)v.get("meatError")).longValue()==0));row.put("newDeaths",((Number)row.get("deaths")).longValue()-r.initialDeaths);r.checks.put("noNewDeaths",((Number)row.get("newDeaths")).longValue()==0);r.checks.put("localSuccessionOnly",state.towns.values().stream().allMatch(v->v.localOnly)&&migration==0);r.checks.put("noInfiniteBuyer",state.towns.keySet().stream().noneMatch(d.state.externalBuyer::contains));}
 void write(MinecraftServer s){try{var path=s.getWorldPath(LevelResource.ROOT).resolve("city_settlements/finite-economy/latest.json");Files.createDirectories(path.getParent());var data=new LinkedHashMap<String,Object>();data.put("version","0.9.6");data.put("households",state.households);data.put("config",state.config);data.put("configRevision",state.configRevision);data.put("timestamp",java.time.OffsetDateTime.now().toString());data.put("run",state.run);data.put("businesses",state.businesses);data.put("people",RuralSettlement.get(s).state.people.values().stream().filter(p->p.family!=null&&RuralSettlement.get(s).state.families.containsKey(p.family)&&state.towns.containsKey(RuralSettlement.get(s).state.families.get(p.family).city)).toList());data.put("families",RuralSettlement.get(s).state.families.values().stream().filter(f->state.towns.containsKey(f.city)).map(f->{var row=new LinkedHashMap<String,Object>();row.put("family",f.id);row.put("city",f.city);row.put("silver",familyMoney(s,f));row.put("wheat",RuralRules.count(RuralSettlement.get(s).stocks(f.id),false));row.put("bread",RuralRules.count(RuralSettlement.get(s).stocks(f.id),true));return row;}).toList());data.put("towns",state.towns);data.put("markets",state.towns.values().stream().map(t->{var row=new LinkedHashMap<String,Object>();row.put("city",t.city);row.put("urban",t.urban);row.put("quotes",java.util.stream.IntStream.range(0,4).map(g->quote(s,t.city,g,RuralSettlement.get(s).state.simulationTicks)).toArray());row.put("stock",java.util.stream.IntStream.range(0,4).map(g->stock(s,t.city,g)).toArray());row.put("targets",java.util.stream.IntStream.range(0,4).map(g->target(s,t.city,g)).toArray());return row;}).toList());data.put("ruralAudit",RuralSettlement.get(s).audit(state.run.village));Files.writeString(path,CityEconomy.JSON.toJson(data));}catch(Exception ex){org.slf4j.LoggerFactory.getLogger("CityTrade").warn("有限经济报告写入失败",ex);}}
 void start(MinecraftServer s){var r=state.run;CityEconomy.require(r.ready&&!r.running&&!r.done,"先创建样板；已开始场景不能重置");prepare(s);var d=RuralSettlement.get(s);for(var town:state.towns.values()){d.state.externalBuyer.remove(town.city);d.state.enabled.add(town.city);var c=CityData.get(s).require(town.city);c.works.enabled=true;c.works.clock=d.state.simulationTicks;c.works.day=d.state.simulationDay;c.works.nextDecay=c.works.clock+72000;c.works.nextSegment=c.works.clock+3000;c.works.nextMeal=c.works.clock+36000;}d.state.speed=30;r.startClock=d.state.simulationTicks;r.startGame=s.overworld().getGameTime();r.startedAt=java.time.OffsetDateTime.now().toString();r.initialMigrationSilver=state.towns.keySet().stream().mapToLong(id->CityData.get(s).require(id).works.migrantSilver).sum();r.initialDeaths=d.state.people.values().stream().filter(p->p.dead&&p.family!=null&&d.state.families.containsKey(p.family)&&state.towns.containsKey(d.state.families.get(p.family).city)).count();r.initialMoney=money(s);r.initialGrain=grain(s);r.initialGoods=goods(s);r.initialMeat=meat(s);r.initialMeatProduced=meatProduced(s);r.initialMeatEaten=meatEaten(s);r.initialHarvest=harvested(s);r.initialBreadEaten=eaten(s);r.running=true;state.nextStep=r.startClock;sample(s);write(s);setDirty();}
}


